Then the n=n/10, untill n = 0. For checking the palindrome you need to store the n in one variable, e.g b = n. Then compare the var with b if theybare same return true else false.

## Solution
class Solution {
public:
    bool isPalindrome(int n) {
        int a = 0 ;
        int dup = n;
        while(n!=0)
        {
            a=(a*10)+(n%10);
            n=n/10;
        }
        if(a==dup)
        {
            return true;
        }
        else{
            return false;
        }
    }
};

